public static void main(String[] args) {
    AReader sc = new AReader();
    int n = sc.nextInt(), m = sc.nextInt();
    int[] x = new int[m + 1];
    long[] d = new long[n + 1];
    for (int i = 1; i <= m; i++) {
        x[i] = sc.nextInt();
    }
    long ans = 0;
    for (int i = 1; i <= m - 1; i++) {
        int from = x[i], to = x[i + 1];
        if (from > to) {
            int temp = from;
            from = to;
            to = temp;
        }
        if (to - from <= n + from - to) {
            int dis = n + from - to - to + from;
            d[from] += dis;
            d[to] -= dis;
            ans += to - from;
        } else {
            int dis = to - from - n - from + to;
            d[1] += dis;
            d[from] -= dis;
            d[to] += dis;
            d[n] -= dis;
            ans += n + from - to;
        }
    }
    long mn = Long.MAX_VALUE;
    for (int i = 1; i <= n; i++) {
        d[i] += d[i - 1];
        mn = Math.min(mn, d[i]);
    }
    PrintWriter pw = new PrintWriter(System.out);
    pw.println(ans + mn);
    pw.close();
}
